for k in ['prefill_bootstrap_setup_ms','prefill_tile_wall_ms','prefill_tile_gpu_ms','prefill_transformer_setup_ms','prefill_transformer_wall_ms','prefill_transformer_gpu_ms','transformer_command_wall_minus_gpu_ms','prefill_host_overhead_ms']:
 x=phase['summary'][k];lines.append(f"| {k} | {x['baseline']['median']/1000:.3f} | {x['candidate']['median']/1000:.3f} | {x['paired_delta_ms']['median']/1000:+.3f} |")
